-- @notransaction
-- 0033_pk_not_null_rebuild.sql
-- @version 1.0.0
-- @reversible: false in the general case (a hand-reverse would need to
--   re-drop NOT NULL, which SQLite also cannot ALTER — same rebuild
--   procedure run in reverse against a pre-migration backup; ADR-0014)
--
-- ADR-0071 — ran to completion. Generated by
-- scripts/co-newbiz/gen-pk-notnull-rebuild.ts from the live schema
-- (db/data/co-newbiz.sqlite) — not hand-authored, to avoid the
-- transcription risk of retyping ~85 CREATE TABLE bodies by hand.
-- Every table below had its single inline "<col> TEXT PRIMARY KEY" rewritten
-- to "<col> TEXT PRIMARY KEY NOT NULL" — nothing else in the table body
-- changed (CHECKs/FKs/UNIQUE/defaults carried through verbatim). Composite-PK
-- tables (already NOT NULL on every constituent column) are not touched.
--
-- Table order below is topologically sorted (FK-referenced parent tables
-- before their children) purely for readability/least-surprise — it is
-- NOT what makes this migration work. The actual blocker, found via
-- sandbox testing against a copy of the live DB (which by this point in
-- the session has real rows — an app_user account, a session, an
-- api_token, all created earlier this session): DROP TABLE of a table
-- with live FK-referencing child ROWS fails ("FOREIGN KEY constraint
-- failed") under foreign_keys=ON, regardless of rebuild order — parent-
-- before-child ordering alone does not fix it, only reduces which tables
-- hit it. The real fix is PRAGMA foreign_keys=OFF for the rebuild's
-- duration, which requires this file to opt out of db/migrate.ts's
-- normal transaction wrapper (see this file's leading
-- "-- @notransaction" marker and db/migrate.ts's header comment) — SQLite
-- documents the foreign_keys pragma as a no-op inside an open
-- transaction, so toggling it only takes effect run outside one.

PRAGMA foreign_keys = OFF;

-- ── md_project (PK: id) ──────────────────────────────────────
CREATE TABLE md_project_new (
  id TEXT PRIMARY KEY NOT NULL,
  project_no TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
, current_stage_gate TEXT
  CHECK (current_stage_gate IS NULL OR current_stage_gate IN ('screening','pre_fs','fs','dd','entity_ic','group_ic')));
INSERT INTO md_project_new SELECT * FROM md_project;
DROP TABLE md_project;
ALTER TABLE md_project_new RENAME TO md_project;

