  asserted_by TEXT NOT NULL,
  reviewed_by TEXT,
  rationale TEXT NOT NULL,
  observed_at TEXT NOT NULL,
  superseded_by TEXT REFERENCES dimension_input(id),
  CHECK ((value_kind='num' AND value_num IS NOT NULL AND value_text IS NULL)
