-- ── watch_rule (PK: id) ──────────────────────────────────────
CREATE TABLE watch_rule_new (
  id TEXT PRIMARY KEY NOT NULL,
  watch_id TEXT NOT NULL REFERENCES watch(id),
  trigger_type TEXT NOT NULL CHECK (
    trigger_type IN ('rag_upgrade', 'rag_downgrade', 'kill_criteria', 'regulation_change', 'threshold_breach', 'staleness', 'batch_failure')
  ),
  -- Interpretation is trigger-specific (e.g. threshold_breach = an IRR/NPV
  -- delta in percentage points); NULL where the trigger has no threshold.
  threshold REAL,
  cooldown_hours INTEGER NOT NULL DEFAULT 24,
  channel TEXT NOT NULL CHECK (channel IN ('in_app', 'email', 'webhook', 'all')),
  enabled INTEGER NOT NULL DEFAULT 1
);
INSERT INTO watch_rule_new SELECT * FROM watch_rule;
DROP TABLE watch_rule;
ALTER TABLE watch_rule_new RENAME TO watch_rule;
CREATE INDEX idx_watch_rule_watch ON watch_rule(watch_id);

-- Re-enable enforcement and verify no dangling reference was introduced
-- by 85 DROP+RENAME cycles run with checking suspended. A non-empty
-- result here would mean this migration corrupted referential
-- integrity — db/migrate.ts does not currently fail the run on that
-- (PRAGMA output isn't inspected by the runner), so this is a manual
-- verification step (see scripts/co-newbiz/gen-pk-notnull-rebuild.ts's
-- own test harness for the automated version of this check).
PRAGMA foreign_keys = ON;
PRAGMA foreign_key_check;
